pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        vm.assume(target != address(0));
        uint256 before = c.depositsCount();
        // Attempt the sendMoney call; it may revert if value > address(this).balance or if target call reverts
        try c.sendMoney(target, value, data) {
            uint256 after = c.depositsCount();
            // If value > 0, the fallback is triggered and depositsCount increments by 1
            if (value > 0) {
                assertTrue(after == before + 1, "depositsCount should increase by 1 when value > 0");
            } else {
                assertTrue(after == before, "depositsCount should not change when value == 0");
            }
        } catch {
            // If the call reverts, depositsCount must not change
            uint256 after = c.depositsCount();
            assertTrue(after == before, "depositsCount should not change on revert");
        }
    }
}

