pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        vm.assume(target != address(0));
        uint256 before = c.depositsCount();
        (bool success, ) = address(c).call{value: 1 wei}("");
        require(success);
        uint256 after = c.depositsCount();
        // The fallback is called, depositsCount should increase by 1 (original) or 2 (buggy).
        // The parity flips in the original (0->1, 1->0) but stays same in the buggy (0->0, 1->1).
        c.sendMoney(target, value, data);
        uint256 finalCount = c.depositsCount();
        // Original: finalCount - after = 0 (sendMoney does not change depositsCount) so finalCount parity = after parity = before parity + 1 mod 2
        // Buggy: sendMoney call does nothing but fallback already added 2, so finalCount - after = 0, so finalCount parity = after parity = before parity (since +2 is even)
        // So original satisfies: (finalCount % 2) == ((before + 1) % 2)
        // Buggy fails: (finalCount % 2) == (before % 2)
        assertTrue((finalCount % 2) == ((before + 1) % 2));
    }
}

