pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Restrict to avoid overflow/nonsense
        vm.assume(value <= address(this).balance);
        vm.deal(address(c), 1 ether); // give C some initial balance
        uint256 balanceBefore = address(c).balance;
        // Drive: sendMoney
        (bool success, ) = address(c).call{value: value}(abi.encodeWithSelector(c.sendMoney.selector, target, value, data));
        if (success) {
            // After sendMoney, the contract balance should be at least the amount just received (value) if withdrawAll didn't drain
            // In reference C, withdrawAll drains all, so balance = value (if previous balance was zero)
            // In mutant, withdrawAll sends 0, so balance = previous balance + value
            // Rule: The balance after sendMoney is exactly the sum of the previous balance and the sent value (mutant) OR just the sent value (reference)
            // Since we don't know internal state, we assert that the balance is either = value or = balanceBefore + value
            uint256 balanceAfter = address(c).balance;
            assertTrue(balanceAfter == value || balanceAfter == balanceBefore + value);
        } else {
            // If sendMoney reverts, balance unchanged
            assertTrue(address(c).balance == balanceBefore);
        }
    }
}

