contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 value, bytes memory data) public {
        // Bound value to avoid overflow, ensure caller is not address(0) for transfer
        vm.assume(caller != address(0) && caller != address(c));
        value = bound(value, 1, address(c).balance);

        // Prank as owner to call withdrawAll (to drain balance before sendMoney)
        vm.prank(c.owner());
        c.withdrawAll();

        // Now send money through sendMoney
        uint256 balanceBefore = address(c).balance;
        vm.prank(c.owner());
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", address(0xdead), value, data));

        if (success) {
            uint256 balanceAfter = address(c).balance;
            assertTrue(balanceAfter <= value, "Balance after sendMoney exceeds value sent");
        } else {
            assertTrue(true); // If sendMoney reverts, property vacuously holds
        }
    }
}

