pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Precondition: ensure value is not zero so sendMoney does not revert due to zero value (though require only checks call success)
        vm.assume(value > 0 && value <= address(c).balance); // ensure contract has enough balance to send? Actually we can fund it
        // Fund the contract with some balance via fallback
        vm.deal(address(c), value);
        // Now call sendMoney, but it will revert if contract balance is insufficient? The call will just forward value; if contract balance < value, call will fail, but sendMoney requires success.
        // Better: fund contract with enough balance so sendMoney can succeed
        vm.deal(address(c), value);
        (bool success, ) = address(c).call{value: value}(""); // fund via fallback to increase depositsCount? Not needed, just balance
        // Actually we need to ensure sendMoney succeeds; so give contract enough balance
        vm.deal(address(c), value);
        uint256 balanceBeforeSend = address(c).balance;
        // Call sendMoney
        c.sendMoney(target, value, data);
        uint256 balanceAfterSend = address(c).balance;
        // Now call withdrawAll
        c.withdrawAll();
        uint256 balanceAfterWithdrawAll = address(c).balance;
        // The reference contract: withdrawAll sends the entire balance, so after withdrawAll, balance should be 0
        // The mutant: withdrawAll sends 0, so balance remains unchanged from before withdrawAll
        // General rule: after withdrawAll, the balance is less than or equal to the balance just before withdrawAll (it never increases)
        // But for the reference it is always 0 (if withdrawAll is called by owner), for mutant it stays the same
        // So we assert that after withdrawAll, balance is at most the balance after sendMoney minus the value sent (since sendMoney drains that value from contract)
        // Actually easier: the contract's balance after withdrawAll must be strictly less than the balance after sendMoney (because withdrawAll drains at least something). For mutant, it stays same, so rule fails.
        assertTrue(balanceAfterWithdrawAll < balanceAfterSend, "WithdrawAll should drain some balance");
    }
}

