import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address target, uint256 value, bytes calldata data) public {
        vm.assume(target != address(c)); // avoid self-call that might reenter?
        vm.assume(value <= address(c).balance); // ensure non-zero balance to avoid trivial case

        uint256 before = c.depositsCount();

        // We call sendMoney; in the reference it reverts if the target call fails, succeeds if target call succeeds
        // Since we cannot know if the target call will succeed, we catch the revert
        try c.sendMoney(target, value, data) {
            // call succeeded => the fallback of *target* was not triggered (depositsCount unchanged)
