            // but that fallback is not on contract C. So depositsCount should be the same.
            uint256 after = c.depositsCount();
            assertTrue(after == before, "sendMoney success should not increase depositsCount");
        } catch {
            // call reverted => no state change
            uint256 after = c.depositsCount();
            assertTrue(after == before, "sendMoney revert should not change depositsCount");
        }
    }
